const input = $input.first()?.json || {};
let fecha = input.fecha;
if (!fecha) {
  const hoy = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  fecha = `${hoy.getFullYear()}-${pad(hoy.getMonth() + 1)}-${pad(hoy.getDate())}`;
}
return [{ json: { fecha } }];

const fecha = $input.first().json.fecha;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';
const headers = { 'X-API-Key': apiKey, 'Content-Type': 'application/json' };
const ventas = await this.helpers.httpRequest({ method: 'GET', url: `${baseUrl}/api/ventas?desde=${fecha}&hasta=${fecha}`, headers, json: true });
const abonos = await this.helpers.httpRequest({ method: 'GET', url: `${baseUrl}/api/abonos?desde=${fecha}&hasta=${fecha}`, headers, json: true });
return [{ json: { fecha, ventas: Array.isArray(ventas) ? ventas : [], abonos: Array.isArray(abonos) ? abonos : [] } }];

const { fecha, ventas, abonos } = $input.first().json;
const FORMAS = ['efectivo', 'tarjeta', 'bizum'];
const ETIQUETA = { efectivo: 'Efectivo', tarjeta: 'Tarjeta', bizum: 'Bizum' };
const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const fmt = (n) => round2(n).toFixed(2);
const porForma = {};
for (const f of FORMAS) porForma[f] = { ventas: 0, abonos: 0, total: 0 };
let totalVentas = 0, totalAbonos = 0;
for (const v of ventas) { const f = FORMAS.includes(v.forma_pago) ? v.forma_pago : 'efectivo'; const imp = Number(v.importe || 0); porForma[f].ventas += imp; totalVentas += imp; }
for (const a of abonos) { const f = FORMAS.includes(a.forma_pago) ? a.forma_pago : 'efectivo'; const imp = Number(a.importe || 0); porForma[f].abonos += imp; totalAbonos += imp; }
for (const f of FORMAS) porForma[f].total = porForma[f].ventas + porForma[f].abonos;
const totalDia = totalVentas + totalAbonos;
const sinMovimientos = ventas.length === 0 && abonos.length === 0;
const [aa, mm, dd] = fecha.split('-');
const fechaTexto = `${dd}/${mm}/${aa}`;
let html;
if (sinMovimientos) {
  html = `<h2>🧾 Cierre de caja · ${fechaTexto}</h2><p>Hola Marisa,</p><p><b>Hoy no hubo movimientos</b>: ni ventas ni abonos registrados el ${fechaTexto}. La caja queda igual.</p><p>Zapatería Paso Firme · Gestión automatizada</p>`;
} else {
  const filas = FORMAS.map((f) => `<tr><td>${ETIQUETA[f]}</td><td style="text-align:right">${fmt(porForma[f].ventas)} €</td><td style="text-align:right">${fmt(porForma[f].abonos)} €</td><td style="text-align:right"><b>${fmt(porForma[f].total)} €</b></td></tr>`).join('');
  html = `<h2>🧾 Cierre de caja · ${fechaTexto}</h2><p>Hola Marisa,</p><p>Esto es lo cobrado hoy (${ventas.length} venta(s) y ${abonos.length} abono(s)):</p><table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Forma de pago</th><th>Ventas</th><th>Abonos</th><th>Total</th></tr>${filas}<tr style="background-color:#f2f2f2"><td><b>Total</b></td><td style="text-align:right"><b>${fmt(totalVentas)} €</b></td><td style="text-align:right"><b>${fmt(totalAbonos)} €</b></td><td style="text-align:right"><b>${fmt(totalDia)} €</b></td></tr></table><p>Total cobrado del día: <b>${fmt(totalDia)} €</b>.</p><p>Zapatería Paso Firme · Gestión automatizada</p>`;
}
return [{ json: { fecha, fecha_texto: fechaTexto, sin_movimientos: sinMovimientos, total_ventas: round2(totalVentas), total_abonos: round2(totalAbonos), total_dia: round2(totalDia), por_forma: porForma, ventas_count: ventas.length, abonos_count: abonos.length, html } }];
